import { createHash } from "node:crypto";

export const CHECKPOINT_ATTACHMENT_BINDING_KINDS = [
  "task-attachment",
  "recovery-instruction",
  "context",
  "external-artifact-ref",
  "ledger-checkpoint",
] as const;

export type CheckpointAttachmentBindingKind =
  (typeof CHECKPOINT_ATTACHMENT_BINDING_KINDS)[number];

export type CheckpointAttachmentBindingStatus =
  | "recovered"
  | "missing-hash"
  | "invalid-hash"
  | "missing-owner"
  | "missing-ttl"
  | "expired"
  | "missing-ref"
  | "invalid-kind"
  | "conflict";

export interface CheckpointAttachmentBinding {
  kind: CheckpointAttachmentBindingKind;
  ref: string;
  attachmentRef?: string;
  contentHash: string;
  owner: string;
  ttlMs: number;
  expiresAt?: string;
}

export interface CheckpointAttachmentBindingCandidate {
  kind?: unknown;
  ref?: unknown;
  attachmentRef?: unknown;
  reference?: unknown;
  contentHash?: unknown;
  hash?: unknown;
  owner?: unknown;
  ttlMs?: unknown;
  expiresAt?: unknown;
  content?: unknown;
  contentBytes?: unknown;
}

export interface CheckpointAttachmentBindingStatusEntry {
  kind?: string;
  ref?: string;
  attachmentRef?: string;
  contentHash?: string;
  owner?: string;
  status: CheckpointAttachmentBindingStatus;
  reason: string;
}

export interface CheckpointAttachmentBindingRecoveryResult {
  recovered: CheckpointAttachmentBinding[];
  excluded: CheckpointAttachmentBindingStatusEntry[];
  statuses: CheckpointAttachmentBindingStatusEntry[];
  digest: string;
}

export interface RecoverCheckpointAttachmentBindingsInput {
  bindings?: readonly CheckpointAttachmentBindingCandidate[];
  candidates?: readonly CheckpointAttachmentBindingCandidate[];
  now?: number | string | Date;
}

const SHA256_HEX = /^[0-9a-f]{64}$/i;
const KIND_SET = new Set<string>(CHECKPOINT_ATTACHMENT_BINDING_KINDS);

function sha256(value: string): string {
  return createHash("sha256").update(value, "utf8").digest("hex");
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function nonEmptyString(value: unknown): string | undefined {
  if (typeof value !== "string") return undefined;
  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : undefined;
}

function ownerId(value: unknown): string | undefined {
  const direct = nonEmptyString(value);
  if (direct) return direct;
  if (!isRecord(value)) return undefined;
  return (
    nonEmptyString(value.id) ??
    nonEmptyString(value.ownerId) ??
    nonEmptyString(value.owner)
  );
}

function resolveNow(now: number | string | Date | undefined): number {
  if (now instanceof Date) return now.getTime();
  if (typeof now === "number" && Number.isFinite(now)) return now;
  if (typeof now === "string") {
    const parsed = Date.parse(now);
    if (Number.isFinite(parsed)) return parsed;
  }
  return Date.now();
}

function normalizeCandidates(
  input: RecoverCheckpointAttachmentBindingsInput | readonly CheckpointAttachmentBindingCandidate[],
): readonly CheckpointAttachmentBindingCandidate[] {
  if (Array.isArray(input)) return input;
  return input.bindings ?? input.candidates ?? [];
}

function candidateContentMatchesHash(
  candidate: CheckpointAttachmentBindingCandidate,
  hash: string,
): boolean {
  if (typeof candidate.content === "string") {
    return sha256(candidate.content) === hash;
  }
  if (candidate.contentBytes instanceof Uint8Array) {
    return createHash("sha256").update(candidate.contentBytes).digest("hex") === hash;
  }
  if (Array.isArray(candidate.contentBytes) &&
      candidate.contentBytes.every((item) => Number.isInteger(item) && item >= 0 && item <= 255)) {
    return createHash("sha256").update(Uint8Array.from(candidate.contentBytes)).digest("hex") === hash;
  }
  return true;
}

function canonicalize(value: unknown): string {
  if (value === null || typeof value !== "object") return JSON.stringify(value);
  if (Array.isArray(value)) return `[${value.map(canonicalize).join(",")}]`;
  const record = value as Record<string, unknown>;
  return `{${Object.keys(record).sort().map((key) => `${JSON.stringify(key)}:${canonicalize(record[key])}`).join(",")}}`;
}

function compareStrings(left: string, right: string): number {
  return left < right ? -1 : left > right ? 1 : 0;
}

function compareBindings(
  left: CheckpointAttachmentBinding,
  right: CheckpointAttachmentBinding,
): number {
  return compareStrings(left.kind, right.kind) ||
    compareStrings(left.ref, right.ref) ||
    compareStrings(left.contentHash, right.contentHash) ||
    compareStrings(left.owner, right.owner) ||
    left.ttlMs - right.ttlMs;
}

function compareStatuses(
  left: CheckpointAttachmentBindingStatusEntry,
  right: CheckpointAttachmentBindingStatusEntry,
): number {
  return compareStrings(left.kind ?? "", right.kind ?? "") ||
    compareStrings(left.ref ?? "", right.ref ?? "") ||
    compareStrings(left.attachmentRef ?? "", right.attachmentRef ?? "") ||
    compareStrings(left.contentHash ?? "", right.contentHash ?? "") ||
    compareStrings(left.owner ?? "", right.owner ?? "") ||
    compareStrings(left.status, right.status) ||
    compareStrings(left.reason, right.reason);
}

function conflictKey(
  kind: CheckpointAttachmentBindingKind,
  ref: string,
  attachmentRef: string | undefined,
): string {
  return attachmentRef ? `attachment:${attachmentRef}` : `${kind}:${ref}`;
}

function bindingIdentity(
  kind: CheckpointAttachmentBindingKind,
  ref: string,
  hash: string,
): string {
  return `${kind}\u0000${ref}\u0000${hash}`;
}

function makeStatus(
  candidate: CheckpointAttachmentBindingCandidate,
  status: CheckpointAttachmentBindingStatus,
  reason: string,
): CheckpointAttachmentBindingStatusEntry {
  const kind = nonEmptyString(candidate.kind);
  const ref = nonEmptyString(candidate.attachmentRef) ??
    nonEmptyString(candidate.ref) ??
    nonEmptyString(candidate.reference);
  const attachmentRef = nonEmptyString(candidate.attachmentRef);
  const rawHash = nonEmptyString(candidate.contentHash) ?? nonEmptyString(candidate.hash);
  const owner = ownerId(candidate.owner);
  return {
    ...(kind ? { kind } : {}),
    ...(ref ? { ref } : {}),
    ...(attachmentRef ? { attachmentRef } : {}),
    ...(rawHash ? { contentHash: rawHash.toLowerCase() } : {}),
    ...(owner ? { owner } : {}),
    status,
    reason,
  };
}

/**
 * Restores checkpoint references without mutating the input. Only the five
 * reference kinds are representable; payload bytes are used for verification
 * when supplied and are never returned as a recoverable binding.
 */
export function recoverCheckpointAttachmentBindings(
  input: RecoverCheckpointAttachmentBindingsInput | readonly CheckpointAttachmentBindingCandidate[],
): CheckpointAttachmentBindingRecoveryResult {
  const candidates = normalizeCandidates(input);
  const now = resolveNow(Array.isArray(input) ? undefined : input.now);
  const recovered: CheckpointAttachmentBinding[] = [];
  const statuses: CheckpointAttachmentBindingStatusEntry[] = [];
  const firstByConflictKey = new Map<string, { kind: CheckpointAttachmentBindingKind; ref: string; hash: string }>();
  const seenIdentities = new Set<string>();

  for (const candidate of candidates) {
    const kindValue = nonEmptyString(candidate.kind);
    if (!kindValue || !KIND_SET.has(kindValue)) {
      statuses.push(makeStatus(candidate, "invalid-kind", "kind is not one of the five permitted reference kinds"));
      continue;
    }
    const kind = kindValue as CheckpointAttachmentBindingKind;
    const attachmentRef = nonEmptyString(candidate.attachmentRef);
    const ref = attachmentRef ??
      nonEmptyString(candidate.ref) ??
      nonEmptyString(candidate.reference);
    if (!ref) {
      statuses.push(makeStatus(candidate, "missing-ref", "reference is missing"));
      continue;
    }

    const hashValue = nonEmptyString(candidate.contentHash) ?? nonEmptyString(candidate.hash);
    if (!hashValue) {
      statuses.push(makeStatus(candidate, "missing-hash", "content hash is missing"));
      continue;
    }
    const contentHash = hashValue.toLowerCase();
    if (!SHA256_HEX.test(contentHash)) {
      statuses.push(makeStatus(candidate, "invalid-hash", "content hash is not a sha256 hex digest"));
      continue;
    }
    if (!candidateContentMatchesHash(candidate, contentHash)) {
      statuses.push(makeStatus(candidate, "invalid-hash", "content does not match the declared sha256 digest"));
      continue;
    }

    const owner = ownerId(candidate.owner);
    if (!owner) {
      statuses.push(makeStatus(candidate, "missing-owner", "owner is missing"));
      continue;
    }

    const ttlMs = typeof candidate.ttlMs === "number" && Number.isFinite(candidate.ttlMs)
      ? candidate.ttlMs
      : undefined;
    let expiresAtMs: number | undefined;
    if (candidate.expiresAt instanceof Date) {
      expiresAtMs = candidate.expiresAt.getTime();
    } else if (typeof candidate.expiresAt === "number" && Number.isFinite(candidate.expiresAt)) {
      expiresAtMs = candidate.expiresAt;
    } else if (typeof candidate.expiresAt === "string" && candidate.expiresAt.trim()) {
      expiresAtMs = Date.parse(candidate.expiresAt);
    }
    if (ttlMs === undefined && expiresAtMs === undefined) {
      statuses.push(makeStatus(candidate, "missing-ttl", "TTL or expiry is missing"));
      continue;
    }
    if ((ttlMs !== undefined && ttlMs <= 0) ||
        (expiresAtMs !== undefined && (!Number.isFinite(expiresAtMs) || expiresAtMs <= now))) {
      statuses.push(makeStatus(candidate, "expired", "binding TTL has expired"));
      continue;
    }

    const key = conflictKey(kind, ref, attachmentRef);
    const first = firstByConflictKey.get(key);
    if (first && first.hash !== contentHash) {
      statuses.push(makeStatus(candidate, "conflict", "reference is already bound to a different content hash"));
      continue;
    }
    if (!first) {
      firstByConflictKey.set(key, { kind, ref, hash: contentHash });
    }

    const identity = bindingIdentity(kind, ref, contentHash);
    if (seenIdentities.has(identity)) {
      statuses.push(makeStatus(candidate, "recovered", "duplicate reference and hash was deduplicated"));
      continue;
    }
    seenIdentities.add(identity);

    const binding: CheckpointAttachmentBinding = {
      kind,
      ref,
      ...(attachmentRef ? { attachmentRef } : {}),
      contentHash,
      owner,
      ttlMs: ttlMs ?? Math.max(0, expiresAtMs! - now),
      ...(candidate.expiresAt instanceof Date
        ? { expiresAt: candidate.expiresAt.toISOString() }
        : typeof candidate.expiresAt === "string" && candidate.expiresAt.trim()
          ? { expiresAt: new Date(expiresAtMs!).toISOString() }
          : {}),
    };
    recovered.push(binding);
    statuses.push({
      kind,
      ref,
      ...(attachmentRef ? { attachmentRef } : {}),
      contentHash,
      owner,
      status: "recovered",
      reason: "binding passed kind, hash, owner, and TTL validation",
    });
  }

  recovered.sort(compareBindings);
  statuses.sort(compareStatuses);
  const excluded = statuses.filter((entry) => entry.status !== "recovered");
  const digest = sha256(canonicalize({ recovered, excluded }));
  return { recovered, excluded, statuses, digest };
}

export const recoverAttachmentBindings = recoverCheckpointAttachmentBindings;

export function digestCheckpointAttachmentBindingRecovery(
  result: CheckpointAttachmentBindingRecoveryResult,
): string {
  return sha256(canonicalize({ recovered: result.recovered, excluded: result.excluded }));
}

# Harness gap: checkpoint attachment binding

## Contract

Checkpoint recovery accepts only these restricted reference kinds:

1. `task-attachment`
2. `recovery-instruction`
3. `context`
4. `external-artifact-ref`
5. `ledger-checkpoint`

Arbitrary cursors and blobs are not recoverable references. Payload bytes may be supplied for hash verification, but they are not persisted in the recovered binding.

Every candidate is checked for:

- a SHA-256 hexadecimal content hash;
- a non-empty owner;
- a TTL (`ttlMs`) or an absolute expiry (`expiresAt`);
- a permitted kind and a non-empty reference.

A missing hash, malformed hash, content/hash mismatch, missing owner, missing TTL, or expired TTL is explicitly excluded. A reference already associated with a different hash is an explicit `conflict`; the first binding is retained. Equal kind/reference/hash candidates are deduplicated.

## Runtime API

`openclaw_runtime/src/runtime-core/checkpoint-attachment-binding.ts` exports:

- `recoverCheckpointAttachmentBindings(input)`;
- `recoverAttachmentBindings(input)` as a compatibility alias;
- `digestCheckpointAttachmentBindingRecovery(result)`;
- runtime-core types and the five permitted kind constants.

The input may be an array of candidates or an object containing `bindings` or `candidates`. `now` may be supplied to make expiry checks deterministic.

## Recovery invariants

Recovery is a pure function. It does not mutate candidates, write files, dispatch messages, update ledgers, execute recovery instructions, or invoke any other side effect. Repeating recovery with the same input and `now` returns the same recovered bindings, statuses, and digest.

Recovered bindings are sorted by kind, reference, hash, owner, and TTL. The digest is SHA-256 over canonical JSON containing only recovered and excluded entries. Status entries make all failures and conflicts visible; invalid and conflicting entries are not included in `recovered`.

## Directional checks

A candidate suite should cover:

- all five accepted kinds and rejection of an arbitrary kind;
- absent, malformed, and mismatched hashes;
- absent owner;
- absent and expired TTL;
- same reference with different hashes (`conflict`, first retained);
- same reference and hash (deduplicated);
- frozen input and identical repeated digest;
- deterministic ordering and digest round-trip.

